def pick_flashback(week: int) -> Dict[str, Any]:
    return FLASHBACK_POOL[week % len(FLASHBACK_POOL)]

def pick_book_of_week(week: int) -> Dict[str, str]:
    return BOOK_POOL[week % len(BOOK_POOL)]

def pick_growth_corner(week: int) -> Dict[str, str]:
    return GROWTH_CORNER_POOL[week % len(GROWTH_CORNER_POOL)]

def pick_wellbeing_tip(week: int) -> Dict[str, str]:
    return WELLBEING_POOL[week % len(WELLBEING_POOL)]

def pick_term_of_week(week: int) -> Dict[str, str]:
    return GLOSSARY_POOL[week % len(GLOSSARY_POOL)]

def pick_engagement_ideas(week: int, count: int = 2) -> List[Dict[str, Any]]:
    n = len(ENGAGEMENT_IDEAS_POOL)
    start = (week * count) % n
    return [ENGAGEMENT_IDEAS_POOL[(start + i) % n] for i in range(count)]

def pick_report_writing_lesson(week: int) -> Dict[str, Any]:
    categories = list(REPORT_WRITING_POOL.keys())
    cat = categories[week % len(categories)]
    lessons = REPORT_WRITING_POOL[cat]
    lesson = lessons[(week // len(categories)) % len(lessons)]
    return {"category": cat, **lesson}
